import{_ as o,C as r,o as s,c as i,a2 as n,b as l,w as a,a as p,E as d,a3 as h}from"./chunks/framework.BC3NdntU.js";const m=JSON.parse('{"title":"11.4 上下文工程(Context / 记忆 / 压缩 / RAG)","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.4-上下文工程.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.4-上下文工程.md","lastUpdated":1788776592000}'),u={name:"卷十一-AIAgentHarness与提示词工程/11.4-上下文工程.md"};function g(c,t,b,E,q,A){const e=r("Mermaid");return s(),i("div",null,[t[1]||(t[1]=n('<h1 id="_11-4-上下文工程-context-记忆-压缩-rag" tabindex="-1">11.4 上下文工程(Context / 记忆 / 压缩 / RAG) <a class="header-anchor" href="#_11-4-上下文工程-context-记忆-压缩-rag" aria-label="Permalink to &quot;11.4 上下文工程(Context / 记忆 / 压缩 / RAG)&quot;">​</a></h1><blockquote><p>卷:卷十一 · AI Agent Harness 与提示词工程 难度:⭐⭐⭐ 专家 | 阅读时间:30min</p></blockquote><hr><h2 id="引言-上下文窗口有限-该放什么-是核心工程问题" tabindex="-1">引言:上下文窗口有限,&quot;该放什么&quot;是核心工程问题 <a class="header-anchor" href="#引言-上下文窗口有限-该放什么-是核心工程问题" aria-label="Permalink to &quot;引言:上下文窗口有限,&quot;该放什么&quot;是核心工程问题&quot;">​</a></h2><p>LLM 的一切能力都建立在&quot;上下文&quot;之上(11.1),但上下文窗口<strong>有限</strong>。上下文工程(Context Engineering)要回答的就一句话:<strong>在有限的窗口里,放哪些内容、以什么结构、按什么顺序,才能让 Agent 最优地完成目标。</strong></p><hr><h2 id="一、上下文是-稀缺资源" tabindex="-1">一、上下文是&quot;稀缺资源&quot; <a class="header-anchor" href="#一、上下文是-稀缺资源" aria-label="Permalink to &quot;一、上下文是&quot;稀缺资源&quot;&quot;">​</a></h2><p>OpenAI 在 harness-engineering 博客里反复强调一个前提:</p><blockquote><p><strong>&quot;情境是一种稀缺资源。一个巨大的指令文件会挤掉任务、代码和相关文档——智能体要么会错过关键约束,要么开始针对错误的约束优化。&quot;</strong></p></blockquote><p>窗口是硬约束,放多了挤掉关键信息,放少了能力不够。所以&quot;塞什么&quot;本身就是最高层的设计决策。</p><p><strong>上下文通常由这些拼起来:</strong></p>',11)),(s(),l(h,null,{default:a(()=>[d(e,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E4%B8%8A%E4%B8%8B%E6%96%87%20Context%5D%20--%3E%20B%5BSystem%20Prompt%3Cbr%2F%3E%E8%A7%92%E8%89%B2%2F%E7%BA%A6%E6%9D%9F%2F%E8%A7%84%E5%88%99%5D%0A%20%20%20%20A%20--%3E%20C%5B%E4%BB%BB%E5%8A%A1%E7%9B%AE%E6%A0%87%3Cbr%2F%3E%E7%94%A8%E6%88%B7%E6%84%8F%E5%9B%BE%5D%0A%20%20%20%20A%20--%3E%20D%5B%E5%8E%86%E5%8F%B2%E6%B6%88%E6%81%AF%3Cbr%2F%3E%E5%AF%B9%E8%AF%9D%2F%E5%8A%A8%E4%BD%9C%2F%E8%A7%82%E5%AF%9F%5D%0A%20%20%20%20A%20--%3E%20E%5B%E5%B7%A5%E5%85%B7%E7%BB%93%E6%9E%9C%3Cbr%2F%3E%E6%A3%80%E7%B4%A2%E7%89%87%E6%AE%B5%2F%E6%89%A7%E8%A1%8C%E8%BE%93%E5%87%BA%5D%0A%20%20%20%20A%20--%3E%20F%5B%E5%A4%96%E9%83%A8%E8%AE%B0%E5%BF%86%3Cbr%2F%3E%E9%95%BF%E6%9C%9F%E7%9F%A5%E8%AF%86%2F%E6%96%87%E6%A1%A3%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[p(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=n(`<hr><h2 id="二、核心原则-地图-而不是说明书" tabindex="-1">二、核心原则:地图,而不是说明书 <a class="header-anchor" href="#二、核心原则-地图-而不是说明书" aria-label="Permalink to &quot;二、核心原则:地图,而不是说明书&quot;">​</a></h2><p>OpenAI 博客里最有名的一条教训:</p><blockquote><p><strong>&quot;给 Codex 的是一张地图,而不是一本 1000 页的说明书。&quot;</strong></p></blockquote><p>他们试过&quot;一个巨大的 AGENTS.md&quot;,结果失败,原因有四(极其精辟):</p><ol><li><strong>挤占窗口</strong>:大指令挤掉任务与代码 → 模型错过关键约束</li><li><strong>过多指导反无效</strong>:当&quot;一切都重要&quot;,就&quot;一切都不重要&quot;→ 模型变成<strong>模式匹配</strong>,而非<strong>有意识导航</strong></li><li><strong>立即腐烂</strong>:庞杂手册变成&quot;过时规则的坟场&quot;,无人维护后悄悄变成麻烦源</li><li><strong>难以核实</strong>:单个大 blob 无法做覆盖/新鲜度/交叉链接的机械检查 → 漂移不可避免</li></ol><p><strong>正确做法:渐进式披露(Progressive Disclosure)</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个小而稳的入口(地图,~100 行)</span></span>
<span class="line"><span>        ↓ 指向</span></span>
<span class="line"><span>更深层的真实信息源(docs/ 结构化目录,按需查阅)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>类比:给新同事的不是全公司规章合订本,而是&quot;一张入职地图 + 遇到问题去哪查&quot;。Agent 同理:先给入口,再让它<strong>按需去查</strong>,而不是一次性灌满。</p></blockquote><hr><h2 id="三、-不在上下文里的东西-不存在" tabindex="-1">三、&quot;不在上下文里的东西 = 不存在&quot; <a class="header-anchor" href="#三、-不在上下文里的东西-不存在" aria-label="Permalink to &quot;三、&quot;不在上下文里的东西 = 不存在&quot;&quot;">​</a></h2><p>这是理解 Agent 局限性的关键一句(OpenAI 博客原文):</p><blockquote><p><strong>&quot;从智能体的角度来看,它在运行时无法在上下文中访问的任何内容,都是不存在的。&quot;</strong></p></blockquote><p>含义:</p><ul><li>存在你脑子里、聊天记录里、Google Docs 里的知识,Agent <strong>统统看不见</strong></li><li>只有<strong>喂进上下文</strong>的,才是它可用的世界</li><li>所以 Agent 工程的一大工作,是<strong>把隐性知识显性化、结构化、放进它能访问的地方</strong>(代码仓库、docs、schema、计划文档)</li></ul><blockquote><p>这直接解释了为什么&quot;代码仓库要作为记录系统(repo as record system)&quot;:把所有该知道的东西,用 Agent 能读、能查、能改的形式<strong>沉淀在仓库里</strong>,Agent 才真正&quot;知道&quot;。</p></blockquote><hr><h2 id="四、记忆的三种形态-时间-性质分层" tabindex="-1">四、记忆的三种形态(时间/性质分层) <a class="header-anchor" href="#四、记忆的三种形态-时间-性质分层" aria-label="Permalink to &quot;四、记忆的三种形态(时间/性质分层)&quot;">​</a></h2><p>Agent 的&quot;记忆&quot;不是一个东西,而是三层:</p><table tabindex="0"><thead><tr><th>层</th><th>存什么</th><th>实现</th><th>生命周期</th></tr></thead><tbody><tr><td><strong>工作记忆</strong></td><td>本轮对话、动作、观察</td><td>直接放上下文</td><td>一次会话</td></tr><tr><td><strong>短期/会话记忆</strong></td><td>多轮历史</td><td>上下文 + 会话存储</td><td>一个任务</td></tr><tr><td><strong>长期记忆</strong></td><td>跨会话的知识、偏好、事实</td><td>向量库 / 文档 / 数据库</td><td>持久</td></tr></tbody></table><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 长期记忆 = 检索增强(RAG):先把知识入库,用时&quot;按相关度捞进上下文&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relevant </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vector_db.search(query, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">top_k</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只取最相关的 5 段</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">context </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> system </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> relevant </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_question</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>为什么检索而非全塞?因为<strong>窗口有限 + 相关性</strong>。全塞塞不下,塞无关的还稀释注意力。RAG 的精髓就是&quot;<strong>用时按需检索</strong>&quot;,是&quot;地图而非说明书&quot;在知识上的延伸。</p></blockquote><hr><h2 id="五、压缩与裁剪-对抗窗口耗尽" tabindex="-1">五、压缩与裁剪:对抗窗口耗尽 <a class="header-anchor" href="#五、压缩与裁剪-对抗窗口耗尽" aria-label="Permalink to &quot;五、压缩与裁剪:对抗窗口耗尽&quot;">​</a></h2><p>长任务里上下文会越滚越大,必须<strong>主动管理</strong>:</p><table tabindex="0"><thead><tr><th>手段</th><th>说明</th></tr></thead><tbody><tr><td><strong>摘要压缩</strong></td><td>把已完成的步骤压缩成简短纪要,替换冗长历史</td></tr><tr><td><strong>滑动窗口</strong></td><td>只保留最近 N 条,更早的丢弃/摘要</td></tr><tr><td><strong>选择性保留</strong></td><td>关键结论、决策、报错<strong>保留原文</strong>,废话裁剪</td></tr><tr><td><strong>分级模型</strong></td><td>便宜的模型先做摘要,省 token</td></tr></tbody></table><blockquote><p>原则:<strong>保留&quot;决策与结论&quot;,裁剪&quot;过程噪音&quot;</strong>。一个任务的上下文管理质量,直接决定它能走多远而不崩、不贵。</p></blockquote><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上下文工程 = 在有限窗口里决定&quot;放什么、怎么组织、按什么顺序&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>核心原则:</span></span>
<span class="line"><span>├─ 上下文是稀缺资源(放多了挤掉关键、稀释注意力)</span></span>
<span class="line"><span>├─ 地图而非说明书:渐进式披露(小入口 → 按需查深层)</span></span>
<span class="line"><span>├─ 不在上下文 = 不存在 → 知识要显性化、结构化、可检索</span></span>
<span class="line"><span>├─ 记忆三层:工作/短期/长期(RAG 按需检索)</span></span>
<span class="line"><span>└─ 压缩裁剪:保留决策结论,裁掉过程噪音</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="七、思考题" tabindex="-1">七、思考题 <a class="header-anchor" href="#七、思考题" aria-label="Permalink to &quot;七、思考题&quot;">​</a></h2><p><strong>Q1:为什么&quot;一个巨大的指令文件&quot;对 Agent 是反效果?</strong></p><p>因为它<strong>挤占有限的上下文窗口</strong>(挤掉任务与代码)、<strong>稀释注意力</strong>(什么都重要=什么都不重要,退化成模式匹配)、<strong>容易腐烂</strong>(过时规则堆成坟场)、<strong>难核实</strong>(大 blob 无法机械检查漂移)。所以要用&quot;地图 + 渐进式披露&quot;,而非&quot;1000 页说明书&quot;。</p><p><strong>Q2:如何给 Agent 设计&quot;长期记忆&quot;?</strong></p><p>把知识<strong>结构化、可检索地</strong>存起来(向量库/文档/数据库),用时<strong>按相关性检索 top-k 进上下文</strong>(RAG),而不是全塞。配合&quot;仓库作为记录系统&quot;:决策、计划、文档都版本化沉淀,Agent 用工具去查,而非靠一次灌满。</p><hr><p>📎 参考:OpenAI《harness-engineering》博客、Anthropic《Building Effective Agents》、LangChain Memory/RAG 文档</p>`,38))])}const _=o(u,[["render",g]]);export{m as __pageData,_ as default};
